/**
 * HPDistance — tiny helper API around HP_DISTANCE_MATRIX.
 *
 *   HPDistance.getKm(fromId, toId)
 *     → real road km between two known place ids, or null if either id
 *       isn't in the matrix (e.g. a gateway city, hotel, or custom point).
 *
 *   HPDistance.getKmWithFallback(fromId, toId, fromCoord, toCoord)
 *     → real km when both ids are in the matrix; otherwise falls back to
 *       haversine * 1.35 (rough road-winding factor) using the supplied
 *       {lat,lng} coords, so callers always get a usable number.
 */
window.HPDistance = (function () {
  function getKm(fromId, toId) {
    if (!fromId || !toId || fromId === toId) return 0;
    const m = window.HP_DISTANCE_MATRIX;
    if (m && m[fromId] && typeof m[fromId][toId] === 'number') return m[fromId][toId];
    if (m && m[toId] && typeof m[toId][fromId] === 'number') return m[toId][fromId]; // reverse direction fallback
    return null;
  }

  function _haversineKm(a, b) {
    const R = 6371, dLat = (b.lat - a.lat) * Math.PI / 180, dLng = (b.lng - a.lng) * Math.PI / 180;
    const s = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * Math.PI / 180) * Math.cos(b.lat * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(s));
  }

  function getKmWithFallback(fromId, toId, fromCoord, toCoord) {
    const exact = getKm(fromId, toId);
    if (exact != null) return exact;
    if (fromCoord && toCoord) return _haversineKm(fromCoord, toCoord) * 1.35;
    return 0;
  }

  return { getKm, getKmWithFallback };
})();
